import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel for fused softplus + tanh + elementwise multiply with input
activation_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_activation_kernel(const float* in, float* out, const int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = in[idx];
        // softplus
        float splus = logf(1.0f + expf(val));
        // tanh(softplus(x)) * x
        out[idx] = tanhf(splus) * val;
    }
}

torch::Tensor fused_activation_cuda(torch::Tensor input) {
    auto size = input.numel();
    auto out = torch::empty_like(input);

    const int block_size = 256;
    const int grid_size = (size + block_size - 1) / block_size;

    fused_activation_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        out.data_ptr<float>(),
        size
    );

    return out;
}
"""

activation_cpp_source = "torch::Tensor fused_activation_cuda(torch::Tensor input);"

activation_module = load_inline(
    name="fused_activation",
    cpp_sources=activation_cpp_source,
    cuda_sources=activation_source,
    functions=["fused_activation_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Custom model that performs a convolution, applies a fused activation,
    and then applies Batch Normalization with custom CUDA optimization for the activation.
    """
    def __init__(self, in_channels, out_channels, kernel_size, eps=1e-5, momentum=0.1):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.bn = nn.BatchNorm2d(out_channels, eps=eps, momentum=momentum)

    def forward(self, x):
        x = self.conv(x)
        x = activation_module.fused_activation_cuda(x)
        x = self.bn(x)
        return x

